/**
 * #2829 W9b — the truth check (design check 5, and Ari's copy refusal).
 *
 * A website must not say what Mingla cannot back (Constitution 9). Copy is
 * scanned for four kinds of claim — numbers, prices, dates and superlatives —
 * and each claim is matched against what IS known: the brand's live
 * offerings (titles, dates, prices, places, sizes), the brand's own words in
 * Mingla, and anything the owner said or pasted that was cited. A claim no
 * source backs comes back as "Check: '500 travellers' isn't backed by
 * anything in Mingla". Pure: it reads text and returns words.
 */

export type ClaimKind = "number" | "price" | "date" | "superlative";
export type Claim = { kind: ClaimKind; text: string };

export type ClaimOffering = {
  id?: string | null;
  title?: string | null;
  summary?: string | null;
  destination_text?: string | null;
  start_at?: string | null;
  end_at?: string | null;
  timezone?: string | null;
  min_price_minor?: number | null;
  currency?: string | null;
  capacity?: number | null;
  spots_left?: number | null;
  group_minimum?: number | null;
};

export type ClaimEvidenceInput = {
  offerings?: readonly ClaimOffering[];
  /** The brand's own words in Mingla (name, description, city…). */
  brandTexts?: readonly (string | null | undefined)[];
  /** Words the owner said or pasted that a change cites. */
  ownerTexts?: readonly (string | null | undefined)[];
};

export type ClaimEvidence = {
  /** Lowercased text corpus (brand words + owner words + offering words). */
  corpus: string;
  numbers: Set<number>;
  /** "YYYY-MM-DD" local dates of offerings. */
  days: Set<string>;
  /** "YYYY-MM" months of offerings. */
  months: Set<string>;
  years: Set<number>;
  /** Prices in major units, per currency ("" = any). */
  prices: Array<{ amount: number; currency: string }>;
};

const MONTHS = ["january", "february", "march", "april", "may", "june", "july", "august", "september", "october", "november", "december"];
const MONTH_RE = "(?:jan(?:uary)?|feb(?:ruary)?|mar(?:ch)?|apr(?:il)?|may|june?|july?|aug(?:ust)?|sep(?:t(?:ember)?)?|oct(?:ober)?|nov(?:ember)?|dec(?:ember)?)";

/** Superlatives and unprovable boasts (a fixed list; a word must stand alone). */
export const SUPERLATIVES: readonly string[] = [
  "best", "#1", "number one", "no. 1", "leading", "top-rated", "top rated", "award-winning", "award winning",
  "world-class", "world class", "unbeatable", "unrivalled", "unrivaled", "unmatched", "cheapest", "lowest price",
  "lowest prices", "most popular", "greatest", "finest", "ultimate", "premier", "guaranteed", "best-selling",
  "bestselling", "highest rated", "highest-rated", "biggest", "largest", "first ever", "only one of its kind",
];

const CURRENCY_SYMBOL: Record<string, string> = { "$": "", "€": "EUR", "£": "GBP", "₦": "NGN" };
const CURRENCY_WORD: Record<string, string> = { usd: "USD", dollars: "USD", eur: "EUR", euros: "EUR", gbp: "GBP", pounds: "GBP", ngn: "NGN", naira: "NGN" };

function toNumber(text: string): number {
  return Number(text.replace(/,/g, ""));
}

function localDay(instant: string, timeZone: string | null | undefined): string | null {
  const time = Date.parse(instant);
  if (!Number.isFinite(time)) return null;
  try {
    const parts = new Intl.DateTimeFormat("en-CA", { timeZone: timeZone || "UTC", year: "numeric", month: "2-digit", day: "2-digit" }).format(new Date(time));
    return /^\d{4}-\d{2}-\d{2}$/.test(parts) ? parts : new Date(time).toISOString().slice(0, 10);
  } catch {
    return new Date(time).toISOString().slice(0, 10);
  }
}

function numbersIn(text: string): number[] {
  return [...text.matchAll(/(?<![\w.])\d[\d,]*(?:\.\d+)?/g)].map((match) => toNumber(match[0])).filter(Number.isFinite);
}

export function buildClaimEvidence(input: ClaimEvidenceInput): ClaimEvidence {
  const texts: string[] = [];
  const numbers = new Set<number>();
  const days = new Set<string>();
  const months = new Set<string>();
  const years = new Set<number>();
  const prices: ClaimEvidence["prices"] = [];
  for (const text of [...(input.brandTexts ?? []), ...(input.ownerTexts ?? [])]) {
    if (typeof text === "string" && text.trim()) texts.push(text);
  }
  for (const offering of input.offerings ?? []) {
    for (const text of [offering.title, offering.summary, offering.destination_text]) if (typeof text === "string") texts.push(text);
    for (const value of [offering.capacity, offering.group_minimum]) if (typeof value === "number") numbers.add(value);
    if (typeof offering.capacity === "number" && typeof offering.spots_left === "number") {
      numbers.add(offering.spots_left);
      numbers.add(Math.max(offering.capacity - offering.spots_left, 0));
    }
    if (typeof offering.min_price_minor === "number") {
      prices.push({ amount: offering.min_price_minor / 100, currency: (offering.currency ?? "").toUpperCase() });
    }
    const start = offering.start_at ? localDay(offering.start_at, offering.timezone) : null;
    const end = offering.end_at ? localDay(offering.end_at, offering.timezone) : null;
    for (const day of [start, end]) {
      if (!day) continue;
      days.add(day);
      months.add(day.slice(0, 7));
      years.add(Number(day.slice(0, 4)));
      numbers.add(Number(day.slice(8, 10)));
      numbers.add(Number(day.slice(0, 4)));
    }
    if (start && end) {
      const span = Math.round((Date.parse(`${end}T00:00:00Z`) - Date.parse(`${start}T00:00:00Z`)) / 86_400_000);
      if (span >= 0) {
        numbers.add(span); // nights
        numbers.add(span + 1); // days
      }
    }
  }
  numbers.add((input.offerings ?? []).length);
  const corpus = texts.join("\n").toLowerCase();
  for (const value of numbersIn(corpus)) numbers.add(value);
  for (const match of corpus.matchAll(/\b(19|20)\d{2}\b/g)) years.add(Number(match[0]));
  return { corpus, numbers, days, months, years, prices };
}

/** Every claim in a piece of copy, in reading order (prices and dates are not also counted as numbers). */
export function findClaims(text: string): Claim[] {
  const claims: Array<Claim & { at: number; end: number }> = [];
  const taken: Array<[number, number]> = [];
  const free = (at: number, end: number) => !taken.some(([a, b]) => at < b && end > a);
  const add = (kind: ClaimKind, at: number, raw: string) => {
    const end = at + raw.length;
    if (!free(at, end)) return;
    taken.push([at, end]);
    claims.push({ kind, text: raw.trim(), at, end });
  };
  const lower = text.toLowerCase();
  const priceRe = /(?:[$€£₦]\s?\d[\d,]*(?:\.\d{1,2})?)|(?:\b\d[\d,]*(?:\.\d{1,2})?\s?(?:usd|eur|gbp|ngn|dollars|euros|pounds|naira)\b)/gi;
  for (const match of text.matchAll(priceRe)) add("price", match.index ?? 0, match[0]);
  const dateRes = [
    new RegExp(`\\b\\d{1,2}(?:st|nd|rd|th)?\\s+(?:of\\s+)?${MONTH_RE}\\b(?:,?\\s+\\d{4})?`, "gi"),
    new RegExp(`\\b${MONTH_RE}\\s+\\d{1,2}(?:st|nd|rd|th)?\\b(?:,?\\s+\\d{4})?`, "gi"),
    new RegExp(`\\b${MONTH_RE}\\s+\\d{4}\\b`, "gi"),
    /\b\d{1,2}[/.]\d{1,2}[/.]\d{2,4}\b/g,
    /\b\d{4}-\d{2}-\d{2}\b/g,
    /\b(?:19|20)\d{2}\b/g,
  ];
  for (const re of dateRes) for (const match of text.matchAll(re)) add("date", match.index ?? 0, match[0]);
  for (const word of SUPERLATIVES) {
    const escaped = word.replace(/[.*+?^${}()|[\]\\#]/g, "\\$&");
    const re = new RegExp(`(?<![\\w-])${escaped}(?![\\w-])`, "g");
    for (const match of lower.matchAll(re)) add("superlative", match.index ?? 0, text.slice(match.index ?? 0, (match.index ?? 0) + word.length));
  }
  // A number with the word after it ("500 travellers"), so the sentence names what was counted.
  for (const match of text.matchAll(/(?<![\w.$€£₦])\d[\d,]*(?:\.\d+)?\+?%?(?:\s+[A-Za-z][A-Za-z'-]*)?/g)) add("number", match.index ?? 0, match[0]);
  return claims.sort((a, b) => a.at - b.at).map(({ kind, text: claimText }) => ({ kind, text: claimText }));
}

function monthIndex(word: string): number {
  const start = word.slice(0, 3).toLowerCase();
  return MONTHS.findIndex((month) => month.startsWith(start));
}

function backed(claim: Claim, evidence: ClaimEvidence): boolean {
  const literal = claim.text.toLowerCase();
  if (literal && evidence.corpus.includes(literal)) return true;
  switch (claim.kind) {
    case "superlative":
      return false;
    case "price": {
      const amount = numbersIn(claim.text)[0];
      if (amount === undefined) return false;
      const symbol = claim.text.trim()[0] ?? "";
      const word = claim.text.toLowerCase().match(/[a-z]+$/)?.[0] ?? "";
      const currency = CURRENCY_SYMBOL[symbol] ?? CURRENCY_WORD[word] ?? "";
      return evidence.prices.some((price) => Math.abs(price.amount - amount) < 0.005 && (!currency || !price.currency || price.currency === currency));
    }
    case "date": {
      const text = claim.text.toLowerCase();
      const iso = text.match(/\b(\d{4})-(\d{2})-(\d{2})\b/);
      if (iso) return evidence.days.has(iso[0]);
      const numeric = text.match(/^(\d{1,2})[/.](\d{1,2})[/.](\d{2,4})$/);
      if (numeric) {
        const year = numeric[3]!.length === 2 ? 2000 + Number(numeric[3]) : Number(numeric[3]);
        const pad = (n: string) => n.padStart(2, "0");
        return evidence.days.has(`${year}-${pad(numeric[2]!)}-${pad(numeric[1]!)}`) || evidence.days.has(`${year}-${pad(numeric[1]!)}-${pad(numeric[2]!)}`);
      }
      const monthWord = text.match(new RegExp(MONTH_RE, "i"))?.[0];
      const year = text.match(/\b(19|20)\d{2}\b/)?.[0];
      const day = text.replace(/\b(19|20)\d{2}\b/, "").match(/\b(\d{1,2})(?:st|nd|rd|th)?\b/)?.[1];
      if (!monthWord) return year !== undefined && evidence.years.has(Number(year));
      const month = String(monthIndex(monthWord) + 1).padStart(2, "0");
      const candidates = [...evidence.days].filter((value) => value.slice(5, 7) === month && (!year || value.startsWith(year)));
      if (day) return candidates.some((value) => Number(value.slice(8, 10)) === Number(day));
      return candidates.length > 0;
    }
    case "number": {
      const value = numbersIn(claim.text)[0];
      return value !== undefined && evidence.numbers.has(value);
    }
  }
}

/** The claims in `text` that nothing backs. */
export function unbackedClaims(text: string, evidence: ClaimEvidence): Claim[] {
  return findClaims(text).filter((claim) => !backed(claim, evidence));
}

/** The owner-facing sentence for an unbacked claim. */
export function claimSentence(claim: Claim): string {
  return `Check: '${claim.text}' isn't backed by anything in Mingla`;
}
